{"content": "def next_recovery(task):
    """Choose the smallest safe recovery action based on task state."""
    # Check if running with a live lease - means wait
    if task.get("running_with_live_lease", False):
        return "wait"

    # Check if queued - means retry
    if task.get("queued", False):
        return "retry"

    # Check failed state
    if task.get("failed", False):
        attempts = task.get("attempts", 0)
        max_attempts = task.get("max_attempts", float('inf'))
        if attempts < max_attempts:
            return "retry"
        else:
            return "escalate"

    # Unknown state
    raise ValueError("Unknown task state")
